#!/usr/bin/env python3
"""
Round 148b (culprits), 3 October 2026. Needs round 147i.

Oil painting, a sixth basemap.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 148b (3 October)\n\nNeeds round 147i. No tiles patch. No app.js?v= bump. Oil painting basemap only.\n\n- A sixth basemap, Oil painting (asked 3 October: like the paintings of JB\n  Clemens and Robert Griffing combined, after the owner\'s two pictures of\n  Clemens\'s work). Taken from them is the way they are painted, not anything\n  in them: visible brush strokes, mist low in the valleys (Griffing), a low\n  sun lighting the faces of slopes over deep shadow (Clemens). Their golds,\n  oranges and greens are turned into the map\'s own colours: navy sea paler\n  over the shelves; misty grey-teal lowlands deepening to slate and dusk\n  cobalt, bone on the highest peaks (AWS terrain heights, sea-dem); bone\n  light from a low western sun over navy shadow (Mapterhorn); a pale haze\n  over ground below 1,500 m; forests a slate-teal wash; lakes and rivers\n  slate blue; towns and roads cool grey (OpenFreeMap); names in grey ink.\n- Brush strokes painted square by square on the reader\'s computer\n  (oilbrush:// protocol, oilBrushPiece, rawPng): broad soft patches under\n  flat-brush strokes whose slant follows a slow wave so neighbours lean\n  alike, dry-brush streaks and ragged ends, small pale dabs like meadow\n  flowers. Each square\'s strokes come from its own seed, and the eight\n  squares round it are painted in where they reach, so no seams (also across\n  the date line). About 70 ms a square in the sandbox.\n- Layers outline-oil-* (OIL_IDS), one block of app.js ("Oil painting, a\n  sixth basemap" to "end of Oil painting"), reached by wrapping\n  basemapPanelHtml and setBasemap after Indigenous\'s wrappers. The wrapper\n  also turns Hell\'s names light again when coming from Indigenous (they were\n  left dark). Not seen against real tiles (the sandbox cannot reach them):\n  check the look live.\n']


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round148b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 147i" not in h.read_text(encoding="utf-8"):
        sys.exit("round148b: round 147i must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round148b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round148b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round148b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ''

if __name__ == "__main__":
    main()
